 let info;try{const response=await fetch('/api/runtime',{signal:AbortSignal.any([lifetime.signal,AbortSignal.timeout(15000)]),cache:'no-store',redirect:'error',credentials:'same-origin'});if(!response.ok)throw Error('Local runtime is unavailable.');info=await response.json();if(info.application!=='Athena'||info.api_version!==1||info.same_origin_only!==true||info.loopback_only!==true||!info.runtime_manifest_sha256)throw Error('A verified unified Athena runtime is required.');}catch(error){if(!disposed){root.textContent=error.message;}return controller;}
 if(disposed)return controller;
 root.innerHTML="<link rel=\"stylesheet\" href=\"STYLE_URL\"><nav class=\"lab-tabs\" aria-label=\"Laboratory panels\"><button data-panel=\"overview\">Overview</button><button data-panel=\"collectors\">Collection</button><button data-panel=\"experiments\">Experiments</button></nav><p id=\"workspace-warning\" role=\"status\"></p><p id=\"lab-search-status\" role=\"status\"></p>\n<div class=\"shell\">\n<main><section id=\"overview\" class=\"panel\"><div class=\"hero\"><div><p class=\"eyebrow\">OBSERVE. EXPERIMENT. IMPROVE.</p><h1>Better is something<br>you <em>prove.</em></h1><p class=\"intro\">A working place for measured improvements.<br>Keep the evidence. Repair the failures. Protect what works.</p></div><div class=\"orbital\" aria-hidden=\"true\"><div class=\"orbit one\"></div><div class=\"orbit two\"></div><div class=\"orbit three\"></div><span class=\"core\">A</span><span class=\"orbit-label\">EVIDENCE AT THE CORE</span></div></div><div class=\"metrics\"><article><span>Pending work</span><strong id=\"pending\">0</strong><small>Queued + running</small></article><article><span>Completed jobs</span><strong id=\"completed\">0</strong><small>Successful execution, not promotion</small></article><article><span>Needs attention</span><strong id=\"failed\">0</strong><small>Failures remain in the record</small></article></div><div class=\"section-title\"><h2>Recent activity</h2><span>Latest 50 jobs</span></div><p id=\"connection\" role=\"status\">Connecting to the local engine\u2026</p><div id=\"jobs\" class=\"jobs\"></div></section>\n<section id=\"collectors\" class=\"panel\" hidden><p class=\"eyebrow\">PUBLIC DATA, EXPLICIT BOUNDARIES</p><h1>Collection <em>without guesswork.</em></h1><p class=\"intro\">Start with one verified source. Keep successful results when a refresh fails.</p><article class=\"collector-card\"><div class=\"collector-top\"><span class=\"provider-icon\">M</span><div><h2>Modrinth</h2><p>Public project metadata</p></div><span class=\"badge ready\">IMPLEMENTED</span></div><p>Collect the canonical ID, title, description, project type and version IDs for one project or a bounded canonical-ID batch. No account, downloads or private content.</p><form id=\"collect-form\"><label for=\"project\">Project ID, slug, or comma-separated canonical IDs</label><div class=\"input-row\"><input id=\"project\" name=\"project\" value=\"sodium\" maxlength=\"512\" required autocomplete=\"off\"><button class=\"primary\" type=\"submit\">Collect metadata <span>\u2197</span></button></div></form><p id=\"collect-status\" role=\"status\"></p></article><article class=\"collector-card\"><h2>Complete Modrinth project response</h2><p>Optional full-response archive: retain original public JSON, including license, compatibility and future metadata fields. Existing projection collection is unchanged. Overview shows a compact receipt; source JSON stays local. No account or linked-file downloads.</p><form id=\"project-archive-form\"><label for=\"project-archive-id\">One project ID or slug</label><div class=\"input-row\"><input id=\"project-archive-id\" maxlength=\"128\" value=\"sodium\" required autocomplete=\"off\"><button class=\"primary\" type=\"submit\">Archive full response</button></div></form><p id=\"project-archive-status\" role=\"status\"></p></article><article class=\"collector-card\"><h2>Inspect a saved response</h2><p>Read local archived project responses, individual version objects or fixed upstream snapshots without fetching their provider or converting their numbers. Upstream snapshots are saved observations, not a fresh release check. Markup and URLs remain inert text. Download preserves the original bytes.</p><form id=\"saved-archive-form\"><label for=\"saved-archive-kind\">Saved record type</label><select id=\"saved-archive-kind\"><option value=\"project\">Project response</option><option value=\"version\">Version object</option><option value=\"upstream\">Saved upstream response</option></select><label for=\"saved-archive-id\">Canonical project/version ID, or fixed source: rustsec, hls, serde-json</label><div class=\"input-row\"><input id=\"saved-archive-id\" maxlength=\"32\" placeholder=\"AANobbMI\" required autocomplete=\"off\"><button class=\"primary\" type=\"submit\">View exact saved JSON</button></div></form><button id=\"cancel-archive-load\" disabled type=\"button\">Cancel load</button><button id=\"show-last-archive\" disabled type=\"button\">Show last verified response</button><p id=\"saved-archive-status\" role=\"status\"></p></article><article class=\"collector-card\"><h2>Modrinth versions</h2><p>Collect 1\u201320 canonical version IDs from the official public API. Retain full JSON, including compatibility, dependencies, changelog and file metadata. File links are not downloaded or executed. Missing responses retain earlier snapshots.</p><form id=\"version-collect-form\"><label for=\"version-collect-ids\">Comma-separated version IDs</label><div class=\"input-row\"><input id=\"version-collect-ids\" maxlength=\"512\" placeholder=\"g6ju16VJ, Ag5S66CF\" required autocomplete=\"off\"><button class=\"primary\" type=\"submit\">Save version metadata</button></div></form><p id=\"version-collect-status\" role=\"status\"></p></article><article class=\"collector-card\"><h2>Official upstream checkpoints</h2><p>Read a fixed public GitHub commit or latest-release record. Full JSON stays local; revisions and metadata drift are separate observations, not automatic upgrades. No account, token, asset download or prototype execution.</p><form id=\"upstream-form\"><label for=\"upstream-source\">Public source</label><div class=\"input-row\"><select id=\"upstream-source\"><option value=\"rustsec\">RustSec advisory database head</option><option value=\"hls\">HLS.js GitHub latest release</option><option value=\"serde-json\">serde_json GitHub latest release</option></select><button class=\"primary\" type=\"submit\">Check upstream</button></div></form><p id=\"upstream-status\" role=\"status\"></p><p>At most 30 requests per local database/hour, provider cooldowns retained. An interrupted request fails closed for manual reconciliation. GitHub latest release is not necessarily registry-newest or preferred.</p></article><article id=\"curseforge-offline-card\" class=\"collector-card\"><div class=\"collector-top\"><span class=\"provider-icon\" aria-hidden=\"true\">C</span><div><h2>CurseForge</h2><p>Synthetic schema preview \u00b7 live collection disabled</p></div><span class=\"badge\">RESEARCH ONLY</span></div><p id=\"curseforge-access-status\">Live collection is disabled: this app has no approved CurseForge credential configuration or transport. No keys are accepted or stored here. A browser login is not an API grant.</p><p>This example is generated by Athena\u2019s offline mapper from fabricated fixtures. It does not fetch a provider, queue a job, write your journal or prove live support.</p><button id=\"curseforge-live-collect\" type=\"button\" disabled aria-describedby=\"curseforge-access-status\">Live collection unavailable</button> <button id=\"curseforge-preview-toggle\" type=\"button\" aria-expanded=\"false\" aria-controls=\"curseforge-preview-json\">Show synthetic mapping</button><pre id=\"curseforge-preview-json\" hidden tabindex=\"0\" aria-label=\"Synthetic CurseForge mapping, not live data\"></pre></article><div class=\"boundary\"><h3>Coverage is earned, not implied.</h3><p>Creator platforms, social networks and other video/game hosts are planned. Their APIs, access rights and authentication requirements must be evaluated individually. This app does not bypass paid access or promise complete platform coverage.</p></div></section>\n<section id=\"experiments\" class=\"panel\" hidden><p class=\"eyebrow\">REAL IMPLEMENTATIONS. COMPLETE OUTPUTS.</p><h1>Let the evidence <em>decide.</em></h1><p class=\"intro\">Faster but unstable is a repair candidate, not a production release.</p><div class=\"pipeline\"><article><b>01</b><h3>Baseline</h3><p>Record the workload, implementation and environment.</p></article><article><b>02</b><h3>Experiment</h3><p>Measure actual code and compare complete results.</p></article><article><b>03</b><h3>Stabilize</h3><p>Preserve failures. Repair causes. Re-test speed and correctness.</p></article><article><b>04</b><h3>Review</h3><p>Missing evidence blocks eligibility. Passing does not deploy.</p></article></div><article class=\"boundary\"><h2>Exact identifier deduplication</h2><p>The executable CLI lab compares a linear implementation with a hash-indexed implementation while retaining first-seen order and exact strings. The unit suite includes 10,000 generated differential cases.</p><p>Run the fixed comparison in the local queue: up to 15 measured pairs, 10,000 generated stress cases and a cooperative 15-second budget. Raw partial results and failures are retained. Missing memory and per-strategy cancellation evidence still block promotion.</p><button id=\"run-experiment\" class=\"primary\" type=\"button\">Run bounded comparison</button><p id=\"experiment-status\" role=\"status\"></p><a href=\"https://github.com/Herbertofury/Athena/tree/main/engineering/apps/atlas-lab\" target=\"_blank\" rel=\"noopener noreferrer\">Read the implementation and limits \u2197</a></article><article class=\"boundary\"><h2>Saved version validation</h2><p>Compare the baseline and isolated fixed-field parser on one saved Modrinth version, retaining exact JSON and identity. Up to 20 measured pairs, 10,000 generated stress variations and a cooperative 15-second budget. Partial samples remain visible and missing acceptance evidence blocks promotion.</p><p>Save the version first in Collection, or use the collect-modrinth-versions CLI with this same database. This action reads one existing snapshot; it does not fetch a provider or execute arbitrary code.</p><form id=\"version-experiment-form\"><label for=\"version-experiment-id\">Saved version ID</label><div class=\"input-row\"><input id=\"version-experiment-id\" maxlength=\"32\" placeholder=\"Eight-character version ID\" required autocomplete=\"off\"><button class=\"primary\" type=\"submit\">Compare saved version</button></div></form><p id=\"version-experiment-status\" role=\"status\"></p></article><p class=\"disclosure\">No autonomous code generator or self-deployment is configured. This is a functioning foundation, not a claim of general recursive self-improvement.</p></section>\n</main></div><dialog id=\"saved-archive-dialog\" class=\"archive-dialog\" aria-labelledby=\"saved-archive-title\"><h2 id=\"saved-archive-title\"></h2><p id=\"saved-archive-meta\"></p><pre id=\"saved-archive-text\" tabindex=\"0\"></pre><button id=\"download-saved-archive\" type=\"button\">Download exact JSON</button><button id=\"close-saved-archive\" type=\"button\">Close</button></dialog>".replace('STYLE_URL',new URL('./style.css',import.meta.url).href);
 const cfToggle=root.getElementById('curseforge-preview-toggle'),cfJson=root.getElementById('curseforge-preview-json');
 cfJson.textContent=JSON.stringify({"evidence": "synthetic_fixtures_only", "liveAcceptance": false, "access": {"state": "missing_key", "responseStatus": null, "networkPerformedByMapper": false, "keyValidityVerified": false, "automaticRetryAllowed": false, "fullSupportAccepted": false}, "receipt": {"kind": "curseforge_project", "identity": {"modId": 700001, "gameId": 432}, "authorIds": [900001], "galleryIds": [3, 2], "logoId": 1, "distributionPermission": {"state": "unknown", "value": null}, "projectSearchAvailability": {"state": "provided", "value": false}, "providedFields": ["authors", "screenshots", "logo", "latestFiles", "allowModDistribution", "isAvailable"], "descriptionPresent": true, "descriptionOwnershipVerified": false, "files": [{"id": 800001, "fileLengthDecimal": "9007199254740993", "availability": {"state": "provided", "value": false}, "earlyAccess": {"state": "provided", "value": true}, "downloadReferenceState": "not_provided", "downloadVerified": false}], "pagination": {"state": "complete_for_captured_query", "index": 0, "pageSize": 50, "resultCount": 1, "totalCount": 1, "completeForQuery": true, "completeImport": false}, "latestFilesAreCompleteHistory": false, "liveAcceptance": false, "fullSupportAccepted": false}},null,2);
 const toggleCfPreview=()=>{if(disposed)return;cfJson.hidden=!cfJson.hidden;cfToggle.setAttribute('aria-expanded',String(!cfJson.hidden));cfToggle.textContent=cfJson.hidden?'Show synthetic mapping':'Hide synthetic mapping';};
